// Traegt hier jeweils die Zeilen ein, deren contentStage manuell zurueckgesetzt werden soll.
// 2026-07-26 (4. Verwendung): 12 Vorgaenge (not_applicable/topic_error), die P7 wegen des
// Wettlaufs gegen P4 (siehe Fix in P7 "Filter WordPress-Kandidaten", 2026-07-26) bereits mit
// der blossen Kurzfassung auf golietz.de veroeffentlicht hat, ohne dass P4 je echten Satire-
// Content erzeugt hat (contentCreatedAt war leer). Reset auf needs_content (nicht needs_summary -
// Analyse/Fakten sind bereits vorhanden, nur P4 soll jetzt nachtraeglich laufen). wordpressPosted/
// wordpressPostId bleiben unangetastet, damit die anschliessende Nachtrags-Aktualisierung des
// bestehenden Live-Posts (statt eines Duplikats) moeglich bleibt.
const TARGETS = [
  { vorgangKey: 'vol_10604', vorgangsnummer: '2026/112', targetStage: 'needs_content' },
  { vorgangKey: 'vol_10584', vorgangsnummer: '2026/101', targetStage: 'needs_content' },
  { vorgangKey: 'vol_10607', vorgangsnummer: '2026/115', targetStage: 'needs_content' },
  { vorgangKey: 'vol_10595', vorgangsnummer: '2026/106', targetStage: 'needs_content' },
  { vorgangKey: 'vol_10580', vorgangsnummer: '2026/097', targetStage: 'needs_content' },
  { vorgangKey: 'vol_10579', vorgangsnummer: '2026/096', targetStage: 'needs_content' },
  { vorgangKey: 'vol_10582', vorgangsnummer: '2026/099', targetStage: 'needs_content' },
  { vorgangKey: 'vol_10598', vorgangsnummer: '2026/108', targetStage: 'needs_content' },
  { vorgangKey: 'vol_10593', vorgangsnummer: '2026/105', targetStage: 'needs_content' },
  { vorgangKey: 'vol_10587', vorgangsnummer: '2026/102', targetStage: 'needs_content' },
  { vorgangKey: 'vol_10597', vorgangsnummer: '2026/107', targetStage: 'needs_content' },
  { vorgangKey: 'vol_10601', vorgangsnummer: '2026/110', targetStage: 'needs_content' }
];

if (!TARGETS.length) {
  throw new Error('[ContentStage-Reset] TARGETS im Node "Konfiguriere Ziele" befuellen.');
}

return TARGETS.map(t => ({
  json: {
    vorgangKey: t.vorgangKey,
    vorgangsnummer: t.vorgangsnummer,
    contentStage: t.targetStage || 'needs_summary',
    headlineChoiceStage: '',
    visualPromptStage: '',
    judgmentChainProcessedAt: '',
    imageHeadline: '',
    imageSubline: '',
    contentErrorReason: '',
    last_error_code: '',
    last_error_message: '',
    last_error_stage: '',
    last_error_at: '',
    next_retry_at: '',
    retry_count: 0
  }
}));
